 root=R/'experiments/prospective_native_width_stress_v1_2026-10-18';source=root/'xtea_width96';terminal=source/'terminal.json';t=json.loads(terminal.read_text());assert t['exit_status']==0 and t['status']=='NATIVE_SUCCESS_PENDING_INDEPENDENT_PHYSICAL_CANONICAL';assert all(sha(k)==h for k,h in {**t['bindings'],**t['files']}.items());epfile=R/'experiments/width_stress_RR_separator_profiles_v2_2026-10-18/xtea_width96/endpoints.json';ep=json.loads(epfile.read_text());graph=Path(ep['inputs']['graph']['path']);assert sha(graph)==ep['graph_sha256']==t['files'][str(graph)];qproof=epfile.parent/'independent_literal_verification_v1.json';v=json.loads(qproof.read_text());assert v['physical_queries']==2450 and v['block_types_grid_and_all_SOURCE_SINK_class_identities_equal_same_NET_place_archive'];assert all(sha(k)==h for k,h in v['bindings'].items());out=R/'experiments/prospective_native_width_stress_postchecks_v1_2026-10-18/xtea_width96';out.mkdir(parents=True);tick=time.perf_counter();physical=audit(graph,source/'output.route');names={int(m[1]):m[2] for l in (source/'output.route').read_text().splitlines() if (m:=NET.match(l))};wanted={ep['net_names'][str(q['net_id'])] for q in ep['connections']};expected=Counter((ep['net_names'][str(q['net_id'])],q['source'],q['sink']) for q in ep['connections']);assert {names[q['net_id']] for q in physical['connections']}==wanted;actual=Counter((names[q['net_id']],q['source'],q['sink']) for q in physical['connections']);assert actual==expected and physical['overflow_units']==0;(out/'physical_audit.json').write_text(json.dumps(physical,separators=(',',':'))+'\n');physical_seconds=time.perf_counter()-tick
 command=t['command'].copy();i=command.index('--write_rr_graph');del command[i:i+2];command+=['--read_rr_graph',str(graph)];assert '--write_rr_graph' not in command;log=(source/'native.log').read_text();cpd=float(re.findall(r'Final critical path delay \(least slack\):\s*([0-9.]+)',log)[-1]);files={str(source/n):sha(source/n) for n in ['design.blif','design.net','design.place','design.net.post_routing','output.route','native.log','rr_graph.xml']};bindings={**closure([Path(__file__)]),**files,str(terminal):sha(terminal),str(epfile):sha(epfile),str(qproof):sha(qproof),str(canonical.binary):sha(canonical.binary),str(canonical.identity):sha(canonical.identity)}
